-- Digital Mandi OS — initial D1 schema blueprint
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS shops (id TEXT PRIMARY KEY, name TEXT NOT NULL, owner_name TEXT, phone TEXT, address TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, shop_id TEXT NOT NULL REFERENCES shops(id), name TEXT NOT NULL, email TEXT UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'operator', active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS parties (id TEXT PRIMARY KEY, shop_id TEXT NOT NULL REFERENCES shops(id), party_type TEXT NOT NULL CHECK(party_type IN ('farmer','miller','both')), name TEXT NOT NULL, village TEXT, mobile TEXT, address TEXT, opening_balance REAL NOT NULL DEFAULT 0, balance_side TEXT CHECK(balance_side IN ('debit','credit')), notes TEXT, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS crops (id TEXT PRIMARY KEY, shop_id TEXT REFERENCES shops(id), name TEXT NOT NULL CHECK(name IN ('धान','गेहूँ','चना')), active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS deals (id TEXT PRIMARY KEY, shop_id TEXT NOT NULL REFERENCES shops(id), deal_no TEXT NOT NULL, deal_type TEXT NOT NULL CHECK(deal_type IN ('commission','own_trade')), crop_id TEXT NOT NULL REFERENCES crops(id), farmer_id TEXT NOT NULL REFERENCES parties(id), miller_id TEXT REFERENCES parties(id), variety TEXT, deal_date TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', notes TEXT, created_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(shop_id,deal_no));
CREATE TABLE IF NOT EXISTS weighments (id TEXT PRIMARY KEY, deal_id TEXT NOT NULL REFERENCES deals(id), weighment_type TEXT NOT NULL CHECK(weighment_type IN ('farmer_in','dispatch','miller_accepted','custom_commission')), gross_kg REAL NOT NULL DEFAULT 0, tare_kg REAL NOT NULL DEFAULT 0, net_kg REAL NOT NULL, bags INTEGER NOT NULL DEFAULT 0, vehicle_no TEXT, weighment_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, entered_by TEXT REFERENCES users(id), reason TEXT);
CREATE TABLE IF NOT EXISTS purchases (id TEXT PRIMARY KEY, deal_id TEXT NOT NULL REFERENCES deals(id), farmer_id TEXT NOT NULL REFERENCES parties(id), crop_id TEXT NOT NULL REFERENCES crops(id), quantity_kg REAL NOT NULL, rate_per_quintal REAL NOT NULL, gross_amount REAL NOT NULL, deductions REAL NOT NULL DEFAULT 0, payable_amount REAL NOT NULL, purchase_mode TEXT NOT NULL CHECK(purchase_mode IN ('commission','own_trade')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sales (id TEXT PRIMARY KEY, deal_id TEXT NOT NULL REFERENCES deals(id), miller_id TEXT NOT NULL REFERENCES parties(id), crop_id TEXT NOT NULL REFERENCES crops(id), quantity_kg REAL NOT NULL, rate_per_quintal REAL NOT NULL, gross_amount REAL NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS commission_rules (id TEXT PRIMARY KEY, shop_id TEXT NOT NULL REFERENCES shops(id), miller_id TEXT REFERENCES parties(id), fixed_per_quintal REAL NOT NULL DEFAULT 0, percentage_rate REAL NOT NULL DEFAULT 0, percentage_base TEXT NOT NULL DEFAULT 'gross_sale' CHECK(percentage_base IN ('gross_sale','custom_base')), weight_basis TEXT NOT NULL DEFAULT 'miller_accepted' CHECK(weight_basis IN ('dispatch','miller_accepted','custom')), effective_from TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS commission_calculations (id TEXT PRIMARY KEY, deal_id TEXT NOT NULL REFERENCES deals(id), rule_id TEXT REFERENCES commission_rules(id), weight_basis TEXT NOT NULL, commission_weight_kg REAL NOT NULL, fixed_per_quintal REAL NOT NULL, fixed_amount REAL NOT NULL, percentage_rate REAL NOT NULL, percentage_base_amount REAL NOT NULL, percentage_amount REAL NOT NULL, total_commission REAL NOT NULL, custom_weight_reason TEXT, approved_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS stock_lots (id TEXT PRIMARY KEY, shop_id TEXT NOT NULL REFERENCES shops(id), deal_id TEXT NOT NULL REFERENCES deals(id), crop_id TEXT NOT NULL REFERENCES crops(id), owner_type TEXT NOT NULL CHECK(owner_type IN ('commission_stock','own_stock','in_transit')), owner_party_id TEXT REFERENCES parties(id), quantity_kg REAL NOT NULL, available_kg REAL NOT NULL, location TEXT, status TEXT NOT NULL DEFAULT 'available', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS dispatches (id TEXT PRIMARY KEY, deal_id TEXT NOT NULL REFERENCES deals(id), stock_lot_id TEXT REFERENCES stock_lots(id), miller_id TEXT NOT NULL REFERENCES parties(id), vehicle_no TEXT, driver_name TEXT, dispatch_weight_kg REAL NOT NULL, dispatched_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, status TEXT NOT NULL DEFAULT 'in_transit');
CREATE TABLE IF NOT EXISTS receipts (id TEXT PRIMARY KEY, dispatch_id TEXT NOT NULL REFERENCES dispatches(id), accepted_weight_kg REAL NOT NULL, shortage_weight_kg REAL NOT NULL DEFAULT 0, received_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, note TEXT);
CREATE TABLE IF NOT EXISTS slips (id TEXT PRIMARY KEY, shop_id TEXT NOT NULL REFERENCES shops(id), slip_no TEXT NOT NULL, slip_type TEXT NOT NULL CHECK(slip_type IN ('farmer','miller')), deal_id TEXT REFERENCES deals(id), party_id TEXT NOT NULL REFERENCES parties(id), snapshot_json TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1, status TEXT NOT NULL DEFAULT 'issued', created_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(shop_id,slip_no));
CREATE TABLE IF NOT EXISTS payments (id TEXT PRIMARY KEY, shop_id TEXT NOT NULL REFERENCES shops(id), party_id TEXT NOT NULL REFERENCES parties(id), deal_id TEXT REFERENCES deals(id), direction TEXT NOT NULL CHECK(direction IN ('in','out')), amount REAL NOT NULL CHECK(amount > 0), method TEXT NOT NULL CHECK(method IN ('cash','bank','upi','cheque','other')), reference_no TEXT, paid_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, note TEXT, created_by TEXT REFERENCES users(id));
CREATE TABLE IF NOT EXISTS ledger_accounts (id TEXT PRIMARY KEY, shop_id TEXT NOT NULL REFERENCES shops(id), code TEXT NOT NULL, name TEXT NOT NULL, account_type TEXT NOT NULL CHECK(account_type IN ('asset','liability','income','expense','equity')), UNIQUE(shop_id,code));
CREATE TABLE IF NOT EXISTS journal_entries (id TEXT PRIMARY KEY, shop_id TEXT NOT NULL REFERENCES shops(id), entry_no TEXT NOT NULL, entry_date TEXT NOT NULL, source_type TEXT NOT NULL, source_id TEXT NOT NULL, narration TEXT, status TEXT NOT NULL DEFAULT 'posted' CHECK(status IN ('draft','posted','reversed')), created_by TEXT REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(shop_id,entry_no));
CREATE TABLE IF NOT EXISTS journal_lines (id TEXT PRIMARY KEY, journal_entry_id TEXT NOT NULL REFERENCES journal_entries(id), account_id TEXT NOT NULL REFERENCES ledger_accounts(id), party_id TEXT REFERENCES parties(id), debit REAL NOT NULL DEFAULT 0, credit REAL NOT NULL DEFAULT 0, CHECK(debit >= 0 AND credit >= 0 AND NOT(debit > 0 AND credit > 0)));
CREATE TABLE IF NOT EXISTS expenses (id TEXT PRIMARY KEY, shop_id TEXT NOT NULL REFERENCES shops(id), deal_id TEXT REFERENCES deals(id), category TEXT NOT NULL, amount REAL NOT NULL CHECK(amount > 0), paid_from TEXT NOT NULL, expense_date TEXT NOT NULL, note TEXT, created_by TEXT REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, shop_id TEXT NOT NULL REFERENCES shops(id), user_id TEXT REFERENCES users(id), entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, action TEXT NOT NULL, before_json TEXT, after_json TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_parties_shop_type ON parties(shop_id,party_type);
CREATE INDEX IF NOT EXISTS idx_deals_shop_date ON deals(shop_id,deal_date);
CREATE INDEX IF NOT EXISTS idx_slips_shop_type_date ON slips(shop_id,slip_type,created_at);
CREATE INDEX IF NOT EXISTS idx_payments_party_date ON payments(party_id,paid_at);
CREATE INDEX IF NOT EXISTS idx_stock_shop_crop ON stock_lots(shop_id,crop_id,status);
